root='F:\AER_RETRA_CASE'; p=fullfile(root,'CCN_FULL_RERUN_20260821','day_20220601','CCN_2022_06_01_grid_qc.mat'); A=load(p,'M','C'); x=A.M(:,:,2); x=x(isfinite(x)&A.C>0); fid=fopen(fullfile(root,'CCN_FULL_RERUN_20260821','day_20220601','unit_sensitivity_grid.txt'),'w'); fprintf(fid,'original min=%g p50=%g p95=%g p99=%g max=%g mean=%g\n',min(x),prctile(x,50),prctile(x,95),prctile(x,99),max(x),mean(x)); for s=[1e-3 1 1e3], y=x*s; fprintf(fid,'scale=%g min=%g p50=%g p95=%g p99=%g max=%g mean=%g\n',s,min(y),prctile(y,50),prctile(y,95),prctile(y,99),max(y),mean(y)); end; fclose(fid);
